{
  "title": "Mitigating RAG Hallucinations via Contradiction-Aware Abstention and Evidence Entailment Verification",
  "research_problem": "Large Language Models relying on Retrieval-Augmented Generation frequently hallucinate or generate ungrounded responses when confronted with conflicting or insufficient evidence passages, failing to abstain appropriately when contextually contradictory data is retrieved.",
  "research_gap": "Bounded search findings indicate that while existing work addresses chunk-free retrieval and contrastive explanations for RAG, current frameworks lack a lightweight inference-time verification mechanism that explicitly detects inter-document contradictions and triggers calibrated model abstention when evidence does not logically entail the answer.",
  "methodology": "We propose a two-stage inference framework combining text entailment transformation and contradiction detection. First, we adopt a frozen encoder with a lightweight learned query transformer to align retrieval embeddings for semantic entailment. Second, we introduce a structured verification module that decomposes retrieved passages into atomic facts, checks for pairwise contradictions, and evaluates logical entailment against the query. If inter-document contradictions exceed a threshold or entailment scores fall below a calibrated confidence margin, the system forces the generator to abstain rather than hallucinate an answer.",
  "expected_contribution": "We hypothesize that explicitly modeling inter-document contradictions and coupling them with a calibrated abstention gate will significantly reduce factual hallucination rates in open-domain QA while preserving answer recall on supported queries.",
  "experimental_setup": "We evaluate on open-domain question answering benchmarks including HotpotQA and subset derivations from REVEAL, using a consumer GPU (12 GB VRAM) for local inference and embedding transformations. We benchmark our pipeline against standard vanilla RAG and contrastive retrieval baselines.",
  "evaluation_strategy": "We measure Exact Match (EM), F1 score, and specifically Abstention Precision/Recall to quantify whether the model correctly abstains on contradictory or insufficient contexts without refusing answerable queries.",
  "feasibility_assumptions": [
    "A consumer GPU with 12 GB VRAM is sufficient to run local inference for small-scale open-source LLMs and embedding transformations without full model retraining.",
    "Publicly available datasets like HotpotQA and REVEAL provide adequate multi-document instances containing conflicting or noisy evidence passages."
  ],
  "search_queries": [
    "contradiction detection in retrieval augmented generation",
    "abstention mechanisms for faithful question answering",
    "transform retrieval textual entailment RAG"
  ],
  "assumption_checks": [
    {
      "assumption": "The lightweight query transformation model can be optimized within local hardware constraints without full LLM fine-tuning.",
      "validation_step": "Train the projection MLP using frozen encoder outputs on a small subset of HotpotQA for 5 epochs and measure gradient stability.",
      "acceptance_criterion": "Training completes within 4 hours on a 12 GB GPU with validation loss decreasing monotonically.",
      "fallback": "Substitute the learned MLP with a fixed rule-based query expansion heuristic."
    },
    {
      "assumption": "Prompt-based atomic fact decomposition and contradiction detection can run reliably on a 7B parameter open-weights model.",
      "validation_step": "Run the 4-step factual decomposition pipeline on a 200-sample validation split and compute agreement with human contradiction labels.",
      "acceptance_criterion": "Achieves at least 65 percent agreement with reference contradiction tags.",
      "fallback": "Use stricter regex parsing filters combined with external NLI entailment classifiers."
    }
  ],
  "prior_work_comparison": [
    {
      "paper_id": "2025.naacl-short.50",
      "shared_mechanism": "Utilizes a transform model to align query embeddings for semantic entailment without re-encoding the corpus.",
      "proposed_difference": "Integrates transform retrieval directly with an explicit inter-document contradiction detector and a calibrated abstention gate, rather than focusing solely on entailment matching.",
      "verification_needed": "Ablate the transform retrieval component to measure its isolated impact on contradiction detection accuracy."
    },
    {
      "paper_id": "2025.naacl-long.557",
      "shared_mechanism": "Constructs contrastive explanations or comparative passages to improve reasoning in RAG.",
      "proposed_difference": "Focuses on automated contradiction detection and programmatic abstention rather than generating qualitative contrastive text demonstrations.",
      "verification_needed": "Compare output refusal accuracy against contrastive prompt demonstrations on ambiguous datasets."
    },
    {
      "paper_id": "2024.acl-long.254",
      "shared_mechanism": "Evaluates reasoning chains for attribution to evidence passages and logical consistency.",
      "proposed_difference": "Applies verification at the retrieved evidence and contradiction-checking stage prior to generation rather than evaluating completed reasoning chains post-hoc.",
      "verification_needed": "Evaluate runtime overhead and error propagation differences between pre-generation filtering and post-hoc verification."
    }
  ]
}
